#!/usr/bin/env python3
"""
股东权利救济路径

股东纠纷最容易输在**前置程序**上——诉请选对了、证据也够，
但因为没先书面请求、没先向监事会提出，被直接驳回起诉。

而且**不同诉请是完全不同的案子**：知情权、盈余分配、解散公司、股权回购、
损害赔偿、股东代表诉讼，各自的主体资格、前置程序、举证责任、诉讼后果都不同。
客户说「我想告我那个合伙人」，律师要先把这句话翻译成一个具体的诉请。

⚠️ **公司法 2024-07-01 修订施行**，注册资本认缴期限、股东失权、董事责任、
   异议股东回购等有重大变化。检索类案时须注意裁判日期。

用法：
    shareholder.py --goal 查账 --shareholding 5 --role 股东
    shareholder.py --list
"""

import argparse
import json
import sys

# 六类诉请。每类的关键在「前置程序」与「主体资格」——错了直接被驳回起诉
CLAIMS = {
    "知情权": {
        "别称": ["查账", "看账本", "查财务", "要资料"],
        "诉请": "请求判令公司提供章程、股东名册、股东会决议、董事会决议、"
                "监事会决议、财务会计报告供查阅复制；查阅会计账簿、会计凭证",
        "主体资格": "现股东。**曾经的股东**在有初步证据证明持股期间权益受损时，"
                    "可请求查阅其持股期间的资料",
        "⚠️前置程序": "**必须先向公司提出书面请求并说明目的**。"
                      "公司拒绝或十五日内未答复的，方可起诉。"
                      "**没有书面请求的记录，起诉会被驳回**——这是本类案件最常见的败因",
        "举证要点": ["股东身份证明", "**书面请求的送达凭证**（EMS 回执、签收记录）",
                     "公司拒绝或逾期未答复的证据"],
        "常见抗辩": "公司主张股东有不正当目的（如为竞争业务）——"
                    "**由公司举证**，股东不必自证目的正当",
        "实务提示": "会计账簿与会计凭证的查阅范围常有争议；"
                    "判决支持后公司仍不配合的，需申请强制执行，**执行难度较高**",
    },
    "盈余分配": {
        "别称": ["分红", "要分红", "不分钱"],
        "诉请": "请求判令公司向股东分配利润",
        "主体资格": "现股东",
        "⚠️前置程序": "原则上**须有股东会关于利润分配的决议**——"
                      "没有决议的，法院一般不介入公司自治，会驳回",
        "举证要点": ["利润分配决议", "公司有可分配利润的证据"],
        "常见抗辩": "公司主张需留存资金经营、无可分配利润",
        "实务提示": "**例外**：控股股东滥用权利（如变相分配、不当高薪、"
                    "关联交易转移利润）导致公司长期不分配、损害其他股东利益的，"
                    "可不以决议为前提。**这条例外是多数分红案的真正出路**，"
                    "但举证难度大",
    },
    "解散公司": {
        "别称": ["散伙", "解散", "僵局", "散了算了"],
        "诉请": "请求判令解散公司",
        "主体资格": "**持有公司全部股东表决权百分之十以上的股东**——"
                    "不足 10% 的无原告资格，直接驳回起诉",
        "⚠️前置程序": "须证明**通过其他途径不能解决**——"
                      "如已尝试协商、转让股权、请求其他股东收购等",
        "举证要点": ["持股 10% 以上的证明", "公司经营管理发生严重困难（**僵局**）",
                     "继续存续会使股东利益受到重大损失",
                     "**已通过其他途径尝试解决而未果的证据**"],
        "常见抗辩": "公司仍在经营、盈利，不构成经营管理严重困难",
        "实务提示": "**「经营管理严重困难」指的是治理僵局，不是亏损**。"
                    "公司持续盈利但股东会、董事会长期无法形成有效决议的，"
                    "同样可能构成；反之只是亏损而治理正常的，一般不支持。"
                    "**这是本类案件最常被误解的一点**",
    },
    "股权回购": {
        "别称": ["退股", "让公司买我的股", "异议股东"],
        "诉请": "请求公司按合理价格收购其股权",
        "主体资格": "**对特定股东会决议投反对票的股东**",
        "⚠️前置程序": "**须在股东会会议上投反对票**并有记录。"
                      "未出席、弃权、投赞成票的，不享有回购请求权",
        "举证要点": ["投反对票的记录", "法定回购情形（连续五年盈利却不分配、"
                     "合并分立转让主要财产、章程规定的营业期限届满而修改章程存续）",
                     "**自决议作出之日起六十日内**未与公司达成协议"],
        "常见抗辩": "不符合法定回购情形；未在法定期限内主张",
        "实务提示": "**六十日与九十日两个期限都很短**：六十日内协商不成的，"
                    "自决议作出之日起九十日内起诉。**过期即丧失**，"
                    "这是最容易错过的一类期限",
    },
    "损害赔偿": {
        "别称": ["赔钱", "被坑了", "转移资产", "损害我的利益"],
        "诉请": "请求控股股东、实际控制人、董事、监事、高管赔偿损失",
        "主体资格": "受损害的股东（**直接损害**）",
        "⚠️前置程序": "无特别前置程序，但**须区分损害的是股东个人权益还是公司利益**",
        "举证要点": ["加害行为", "损害后果", "因果关系", "过错"],
        "常见抗辩": "损害的是公司利益而非股东个人利益，股东无权直接索赔",
        "实务提示": "**这是最容易搞错的分岔口**：损害公司利益的（如掏空公司、"
                    "关联交易输送），股东不能直接起诉要求赔给自己，"
                    "**必须走股东代表诉讼**，赔偿归公司。"
                    "只有直接损害股东个人权益的（如剥夺表决权、伪造签名转让股权），"
                    "才能直接索赔",
    },
    "股东代表诉讼": {
        "别称": ["代表公司起诉", "替公司告", "公司被掏空"],
        "诉请": "代表公司请求侵害公司利益的董监高或他人赔偿公司损失",
        "主体资格": "有限责任公司股东；股份有限公司连续一百八十日以上"
                    "单独或合计持股百分之一以上的股东",
        "⚠️前置程序": "**必须先书面请求监事会（或董事会）向法院起诉**。"
                      "监事会/董事会拒绝、或收到请求之日起三十日内未起诉、"
                      "或情况紧急不立即起诉将使公司利益受难以弥补的损害的，"
                      "股东方可自己起诉。"
                      "**跳过这一步直接起诉的，会被驳回**",
        "举证要点": ["股东资格与持股期限", "**书面请求的送达凭证**",
                     "监事会/董事会拒绝或逾期未起诉的证据", "侵害公司利益的行为与损失"],
        "常见抗辩": "未履行前置程序；被告行为未损害公司利益",
        "实务提示": "**胜诉利益归公司，不归提起诉讼的股东**。"
                    "这一点必须提前跟客户说清——很多股东以为赔偿会打给自己",
    },
}


def match_goal(goal):
    for name, c in CLAIMS.items():
        if goal in name or any(a in goal for a in c["别称"]):
            return name
    return None


def main():
    p = argparse.ArgumentParser(description="股东权利救济路径",
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--goal", help="客户想达到什么，如 查账 / 分红 / 退股 / 散伙 / 赔钱")
    p.add_argument("--claim", choices=list(CLAIMS), help="直接指定诉请类型")
    p.add_argument("--shareholding", type=float, help="持股比例（%）")
    p.add_argument("--company-type", dest="company_type", default="有限责任公司",
                   choices=["有限责任公司", "股份有限公司"])
    p.add_argument("--list", action="store_true", help="列出六类诉请")
    args = p.parse_args()

    if args.list:
        print(json.dumps({n: {"别称": c["别称"], "诉请": c["诉请"][:40] + "…"}
                          for n, c in CLAIMS.items()}, ensure_ascii=False, indent=2))
        return

    name = args.claim or (match_goal(args.goal) if args.goal else None)
    if not name:
        print(json.dumps({
            "结果": "未能从描述中识别诉请类型",
            "提示": "客户说「我想告我那个合伙人」时，律师要先把它翻译成一个具体的诉请。"
                    "**不同诉请是完全不同的案子**——主体资格、前置程序、举证责任、"
                    "诉讼后果都不同。请追问客户真正想要什么：查账 / 分红 / 退股 / "
                    "解散公司 / 索赔 / 追回公司被侵占的财产",
            "六类诉请": list(CLAIMS),
        }, ensure_ascii=False, indent=2))
        return

    c = CLAIMS[name]
    checks = []

    # 主体资格的硬门槛
    if name == "解散公司" and args.shareholding is not None:
        ok = args.shareholding >= 10
        checks.append({
            "项": "持股比例", "结果": "✅ 满足" if ok else "❌ **不满足**",
            "说明": f"持股 {args.shareholding}%，要求**全部股东表决权 10% 以上**。"
                    + ("" if ok else "**不足 10% 的无原告资格，起诉会被直接驳回**——"
                                     "可考虑联合其他股东合计达标")})
    if name == "股东代表诉讼" and args.company_type == "股份有限公司" \
            and args.shareholding is not None:
        ok = args.shareholding >= 1
        checks.append({
            "项": "持股比例与期限", "结果": "✅ 满足" if ok else "❌ **不满足**",
            "说明": f"股份有限公司要求**连续一百八十日以上单独或合计持股 1% 以上**；"
                    f"当前 {args.shareholding}%" + ("" if ok else "，且须核实持股期限")})

    other = [n for n in CLAIMS if n != name]
    print(json.dumps({
        "识别的诉请": name,
        "诉请内容": c["诉请"],
        "主体资格": c["主体资格"],
        "⚠️ 前置程序（最常见的败因）": c["⚠️前置程序"],
        "资格核查": checks or "未提供持股比例，无法核查主体资格门槛",
        "举证要点": c["举证要点"],
        "对方常见抗辩": c["常见抗辩"],
        "实务提示": c["实务提示"],
        "其他可能的诉请": other,
        "提示": [
            "**前置程序是股东纠纷最常见的败因。** 诉请选对、证据也够，"
            "但因为没先书面请求、没先向监事会提出，被直接驳回起诉",
            "**书面请求必须有送达凭证。** EMS 回执、签收记录、公证送达——"
            "口头请求等于没请求",
            "**先厘清损害的是公司利益还是股东个人权益。** 损害公司利益的必须走"
            "股东代表诉讼，赔偿归公司；只有直接损害股东个人权益的才能直接索赔。"
            "**这是最容易搞错的分岔口**",
            "⚠️ **公司法 2024-07-01 修订施行**，注册资本认缴期限、股东失权、"
            "董事责任、异议股东回购等有重大变化。检索类案时须注意裁判日期，"
            "修订前的案例参考价值有限",
            "多个诉请可能同时可用（如既要查账又要退股），但**诉讼策略上通常先易后难**——"
            "知情权诉讼拿到账册后，往往能为后续的损害赔偿或回购提供证据",
        ],
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
